  insert into public.exercise_images (exercise_id, url, display_order) values (v_exercise_id, 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Arm_Dumbbell_Pullover/0.jpg', 0);
