  insert into public.exercise_images (exercise_id, url, display_order) values (v_exercise_id, 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Flat_Bench_Lying_Leg_Raise/1.jpg', 1);
